body { margin: 8px; font: 14px sans-serif; }
iframe { width: 380px; height: 90px; border: 1px solid #888; }
.row { display: flex; gap: 8px; align-items: center; }
#below { margin-top: 1400px; }
.badge::before { content: "New"; }

customElements.define('shadow-host', class extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({ mode: 'open' }).innerHTML = '<button id="shadow-action">Shadow action</button>';
  }
});
